export module geo.vec;

namespace geo {

export struct Vec2 {
    double x;
    double y;
};

export Vec2 Add(Vec2 a, Vec2 b) {
    return {a.x + b.x, a.y + b.y};
}

export double Cross(Vec2 a, Vec2 b) {
    return a.x * b.y - a.y * b.x;
}

}  // namespace geo

module;

#include <cmath>

export module geo.shape;

import geo.vec;

namespace geo {

export double TriangleArea(double ax, double ay, double bx, double by) {
    Vec2 a{ax, ay};
    Vec2 b{bx, by};
    return std::fabs(Cross(a, b)) / 2.0;
}

}  // namespace geo

